        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${h.x}%`,
              top: `${h.y}%`,
              opacity,
              transform: `translateY(${y}px) scale(${scale})`,
              fontSize: h.size,
              fontWeight: 700,
              color: h.color,
              fontFamily: "'Inter', sans-serif",
              letterSpacing: "-0.02em",
              whiteSpace: "nowrap",
              userSelect: "none",
