          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
          gap: 60,
        }}
      >
        <div
          style={{
            opacity: labelProgress,
            transform: `translateY(${interpolate(labelProgress, [0, 1], [40, 0])}px)`,
            fontSize: 80,
            fontWeight: 700,
            color: COLORS.white,
            letterSpacing: "-0.03em",
            textAlign: "center",
          }}
        >
          Anyone can create a hashtag.
        </div>

        {/* Bar visual */}
        <div
          style={{
            display: "flex",
            gap: 18,
            alignItems: "flex-end",
            height: 320,
            opacity: barProgress,
            transform: `scale(${interpolate(barProgress, [0, 1], [0.9, 1])})`,
          }}
        >
          {Array.from({ length: totalBars }).map((_, i) => {
            const isActive = i < activeBars;
            const heightPct = isActive
              ? 0.7 + Math.random() * 0.3
              : 0.1 + (i % 5) * 0.04;
            const itemProgress = spring({
              frame,
              fps,
              delay: 30 + i * 3,
              config: { damping: 200 },
            });
            return (
              <div
                key={i}
                style={{
                  width: 36,
                  height: `${heightPct * 100}%`,
                  backgroundColor: isActive
                    ? COLORS.orange
                    : "rgba(255,255,255,0.12)",
                  borderRadius: 6,
                  opacity: itemProgress,
                  transform: `scaleY(${itemProgress})`,
                  transformOrigin: "bottom",
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        <div
          style={{
            opacity: activeProgress,
            transform: `translateY(${interpolate(activeProgress, [0, 1], [30, 0])}px)`,
            fontSize: 52,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "-0.02em",
            textAlign: "center",
